        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 15027.0, "series": [{"data": [[200.0, 1.0]], "isOverall": false, "label": "[verificación] POST procesar", "isController": false}, {"data": [[0.0, 7259.0], [100.0, 266.0], [200.0, 3.0]], "isOverall": false, "label": "POST /api/pedidos/procesar", "isController": false}, {"data": [[100.0, 1.0]], "isOverall": false, "label": "[verificación] GET detalle", "isController": false}, {"data": [[0.0, 15027.0]], "isOverall": false, "label": "GET /api/pedidos/detalle/{id}", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 200.0, "title": "Response Time Distribution"}},
